@startuml

class ResearchGroup {
  + name : string
}

class Department {
  + name : string
}

class Researcher {
  + name : string
  + researcherId : int
}

class Project {
  + title : string
  + projectId : int
}

class WorkPackage {
  + wpName : string
}

class Assignment {
  + assignmentId : int
}

Department "1" -- "*" ResearchGroup
ResearchGroup "1" -- "*" Researcher
Project "1" *-- "1..*" WorkPackage
WorkPackage "1" -- "1" ResearchGroup : ledBy
WorkPackage "1" -- "*" Assignment
Researcher "1" -- "*" Assignment
Assignment "*" -- "1" WorkPackage

@enduml

